'use client';

import React, { useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useI18n } from '../lib/i18n';
import { useSidebar } from '../lib/sidebar';

const LOGO_BASE64 = 'data:image/png;base64,';

interface NavItem {
  key: string;
  href: string;
  labelKey: string;
  icon: (active: boolean) => React.ReactNode;
}

interface NavGroup {
  groupKey: string;
  items: NavItem[];
}

export function Sidebar() {
  const pathname = usePathname();
  const { t, locale, setLocale } = useI18n();
  const { collapsed, toggleCollapsed, mobileOpen, toggleMobileOpen, closeMobile } = useSidebar();

  // Close mobile drawer on route navigation
  useEffect(() => {
    closeMobile();
  }, [pathname, closeMobile]);

  const groups: NavGroup[] = [
    {
      groupKey: 'grp_overview',
      items: [
        {
          key: 'dashboard',
          href: '/dashboard',
          labelKey: 'nav_dashboard',
          icon: () => (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <rect x="3" y="3" width="7" height="9" /><rect x="14" y="3" width="7" height="5" />
              <rect x="14" y="12" width="7" height="9" /><rect x="3" y="16" width="7" height="5" />
            </svg>
          ),
        },
      ],
    },
    {
      groupKey: 'grp_emission',
      items: [
        {
          key: 'tracker',
          href: '/tracker',
          labelKey: 'nav_tracker',
          icon: () => (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="18" y1="20" x2="18" y2="10" /><line x1="12" y1="20" x2="12" y2="4" /><line x1="6" y1="20" x2="6" y2="14" />
            </svg>
          ),
        },
        {
          key: 'assess',
          href: '/assess',
          labelKey: 'nav_assess',
          icon: () => (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
            </svg>
          ),
        },
      ],
    },
    {
      groupKey: 'grp_credit',
      items: [
        {
          key: 'tokenize',
          href: '/tokenize',
          labelKey: 'nav_tokenize',
          icon: () => (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="10" /><line x1="12" y1="8" x2="12" y2="12" /><line x1="12" y1="16" x2="12.01" y2="16" />
            </svg>
          ),
        },
        {
          key: 'market',
          href: '/market',
          labelKey: 'nav_market',
          icon: () => (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="9" cy="21" r="1" /><circle cx="20" cy="21" r="1" />
              <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6" />
            </svg>
          ),
        },
        {
          key: 'portfolio',
          href: '/portfolio',
          labelKey: 'nav_portfolio',
          icon: () => (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z" />
            </svg>
          ),
        },
      ],
    },
    {
      groupKey: 'grp_compliance',
      items: [
        {
          key: 'audit',
          href: '/audit',
          labelKey: 'nav_audit',
          icon: () => (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="22 12 18 12 15 21 9 3 6 12 2 12" />
            </svg>
          ),
        },
        {
          key: 'settings',
          href: '/settings',
          labelKey: 'nav_settings',
          icon: () => (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="3" />
              <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z" />
            </svg>
          ),
        },
      ],
    },
  ];

  const renderNavContent = (isMobile = false) => {
    const isCollapsed = !isMobile && collapsed;

    return (
      <div className="flex flex-col h-full w-full overflow-hidden select-none">
        {/* Brand Header */}
        <div className={`h-16 flex items-center border-b border-white/10 shrink-0 overflow-hidden ${isCollapsed ? 'justify-center px-1.5' : 'px-3.5 gap-2 justify-between'}`}>
          {/* Logo button — toggles collapse on desktop, closes drawer on mobile */}
          <button
            type="button"
            onClick={isMobile ? closeMobile : toggleCollapsed}
            className="shrink-0 w-9 h-9 rounded-xl flex items-center justify-center hover:bg-white/10 transition duration-150 focus:outline-none"
            title={isMobile ? 'Close menu' : (collapsed ? t('sidebar_expand') : t('sidebar_collapse'))}
            aria-label={isMobile ? 'Close menu' : 'Toggle sidebar'}
          >
            <img
              src={LOGO_BASE64}
              alt="ClimaLedger Logo"
              width={28}
              height={28}
              className="w-7 h-7 rounded object-contain"
            />
          </button>

          {/* App name + tagline — visible when expanded */}
          {!isCollapsed && (
            <Link
              href="/dashboard"
              className="flex flex-col flex-1 min-w-0 overflow-hidden leading-tight"
              title="ClimaLedger Dashboard"
            >
              <span className="text-white font-extrabold tracking-tight text-[15px] whitespace-nowrap overflow-hidden text-ellipsis">
                {t('app_name')}
              </span>
              <span className="text-[10px] font-semibold text-emerald-400 uppercase tracking-widest whitespace-nowrap">
                {t('app_tag')}
              </span>
            </Link>
          )}

          {/* Mobile close button on the right */}
          {isMobile && (
            <button
              type="button"
              onClick={closeMobile}
              className="ml-auto text-slate-400 hover:text-white p-2 rounded-xl hover:bg-white/10 transition"
              aria-label="Close menu"
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="18" y1="6" x2="6" y2="18" /><line x1="6" y1="6" x2="18" y2="18" />
              </svg>
            </button>
          )}
        </div>


        {/* Nav Items List */}
        <nav className={`flex-1 overflow-y-auto overflow-x-hidden ${isCollapsed ? 'py-2 px-1 space-y-3' : 'px-3 py-4 space-y-4'}`}>
          {groups.map((group) => (
            <div key={group.groupKey} className="space-y-1">
              {/* Group header: hidden in collapsed mode */}
              {!isCollapsed && (
                <div className="px-3 text-[10px] font-bold uppercase tracking-wider text-slate-500 mb-1 whitespace-nowrap overflow-hidden">
                  {t(group.groupKey)}
                </div>
              )}

              {group.items.map((item) => {
                const active = pathname === item.href;
                return (
                  <div key={item.key} className="relative group">
                    <Link
                      href={item.href}
                      className={`flex items-center rounded-xl transition duration-150 ${
                        isCollapsed
                          ? 'w-10 h-10 mx-auto justify-center'
                          : 'gap-3 px-3 py-2.5 w-full'
                      } ${
                        active
                          ? 'bg-emerald-500/20 text-emerald-400 font-semibold shadow-inner'
                          : 'text-slate-400 hover:text-white hover:bg-white/5'
                      }`}
                    >
                      <span className="shrink-0 flex items-center justify-center">
                        {item.icon(active)}
                      </span>
                      {!isCollapsed && (
                        <span className="truncate text-sm whitespace-nowrap overflow-hidden">
                          {t(item.labelKey)}
                        </span>
                      )}
                    </Link>

                    {/* Tooltip on hover for collapsed mode */}
                    {isCollapsed && (
                      <div className="pointer-events-none fixed left-16 ml-2 hidden group-hover:flex items-center px-2.5 py-1.5 text-xs font-semibold text-white bg-slate-900 rounded-lg shadow-xl border border-slate-700 whitespace-nowrap z-50">
                        {t(item.labelKey)}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          ))}
        </nav>

        {/* Sidebar Footer */}
        <div className="mt-auto border-t border-white/10 shrink-0">
          {!isCollapsed ? (
            <div className="p-3.5 space-y-2.5 text-xs">
              {/* Compliance Badges */}
              <div className="flex justify-between items-center text-[11px]">
                <span className="text-slate-400 font-medium">{t('kyb')}</span>
                <span className="inline-flex items-center gap-1 font-bold text-emerald-400">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block" />
                  {t('kyb_pass')}
                </span>
              </div>
              <div className="flex justify-between items-center text-[11px]">
                <span className="text-slate-400 font-medium">{t('iso')}</span>
                <span className="inline-flex items-center gap-1 font-bold text-emerald-400">
                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block" />
                  {t('iso_pass')}
                </span>
              </div>

              {/* In-sidebar language switch */}
              <div className="pt-2 border-t border-white/5 flex items-center justify-between">
                <span className="text-[11px] text-slate-400 font-medium">{t('dash_lang_label')}</span>
                <div className="inline-flex rounded-lg border border-white/10 bg-white/5 p-0.5">
                  <button
                    type="button"
                    onClick={() => setLocale('id')}
                    className={`px-2 py-0.5 rounded text-[10px] font-bold transition ${
                      locale === 'id' ? 'bg-emerald-500 text-slate-950 font-black' : 'text-slate-400 hover:text-white'
                    }`}
                  >
                    ID
                  </button>
                  <button
                    type="button"
                    onClick={() => setLocale('en')}
                    className={`px-2 py-0.5 rounded text-[10px] font-bold transition ${
                      locale === 'en' ? 'bg-emerald-500 text-slate-950 font-black' : 'text-slate-400 hover:text-white'
                    }`}
                  >
                    EN
                  </button>
                </div>
              </div>
            </div>
          ) : (
            /* Collapsed Footer: Compact language toggle pill */
            <div className="p-2 flex flex-col items-center gap-2">
              <button
                type="button"
                onClick={() => setLocale(locale === 'id' ? 'en' : 'id')}
                className="w-10 h-8 rounded-lg bg-white/5 hover:bg-white/10 border border-white/10 text-emerald-400 hover:text-emerald-300 text-[11px] font-extrabold flex items-center justify-center transition"
                title={`Switch to ${locale === 'id' ? 'English' : 'Bahasa Indonesia'}`}
              >
                {locale.toUpperCase()}
              </button>
              <div className="w-2 h-2 rounded-full bg-emerald-400" title="ISO 14064 & KYB Verified" />
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <>
      {/* 1. Desktop Sidebar (~260px expanded, ~64px collapsed icon-only rail) */}
      <aside
        className={`hidden md:flex flex-col bg-slate-950 text-slate-300 shrink-0 sticky top-0 h-screen transition-[width] duration-200 ease-in-out overflow-hidden whitespace-nowrap z-40 border-r border-slate-800/60 ${
          collapsed ? 'w-16' : 'w-64'
        }`}
      >
        {renderNavContent(false)}
      </aside>

      {/* 2. Mobile Drawer Backdrop & Drawer (<768px) */}
      {mobileOpen && (
        <div
          className="fixed inset-0 bg-slate-950/80 backdrop-blur-xs z-50 md:hidden transition-opacity duration-200"
          onClick={closeMobile}
          aria-hidden="true"
        />
      )}
      <aside
        className={`fixed inset-y-0 left-0 w-64 z-50 md:hidden flex flex-col bg-slate-950 text-slate-300 shadow-2xl transition-transform duration-200 ease-in-out border-r border-slate-800 ${
          mobileOpen ? 'translate-x-0' : '-translate-x-full pointer-events-none'
        }`}
      >
        {renderNavContent(true)}
      </aside>

      {/* 3. Mobile Fixed Bottom Navigation Bar (<768px) */}
      <nav className="md:hidden fixed bottom-0 inset-x-0 h-16 bg-slate-950/95 backdrop-blur-md border-t border-white/10 z-40 flex items-center justify-around px-2 shadow-lg">
        {/* Dashboard */}
        <Link
          href="/dashboard"
          className={`flex flex-col items-center justify-center flex-1 py-1 text-[10px] font-semibold transition ${
            pathname === '/dashboard' ? 'text-emerald-400 font-bold' : 'text-slate-400 hover:text-white'
          }`}
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <rect x="3" y="3" width="7" height="9" /><rect x="14" y="3" width="7" height="5" />
            <rect x="14" y="12" width="7" height="9" /><rect x="3" y="16" width="7" height="5" />
          </svg>
          <span className="truncate max-w-[56px] mt-0.5">{t('nav_dashboard')}</span>
        </Link>

        {/* Tracker */}
        <Link
          href="/tracker"
          className={`flex flex-col items-center justify-center flex-1 py-1 text-[10px] font-semibold transition ${
            pathname === '/tracker' ? 'text-emerald-400 font-bold' : 'text-slate-400 hover:text-white'
          }`}
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <line x1="18" y1="20" x2="18" y2="10" /><line x1="12" y1="20" x2="12" y2="4" /><line x1="6" y1="20" x2="6" y2="14" />
          </svg>
          <span className="truncate max-w-[56px] mt-0.5">{t('nav_tracker')}</span>
        </Link>

        {/* Tokenize */}
        <Link
          href="/tokenize"
          className={`flex flex-col items-center justify-center flex-1 py-1 text-[10px] font-semibold transition ${
            pathname === '/tokenize' ? 'text-emerald-400 font-bold' : 'text-slate-400 hover:text-white'
          }`}
        >
          <div className="w-8 h-8 rounded-full bg-emerald-600/30 text-emerald-400 flex items-center justify-center -mt-2 shadow-xs border border-emerald-500/40">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <circle cx="12" cy="12" r="10" /><line x1="12" y1="8" x2="12" y2="12" /><line x1="12" y1="16" x2="12.01" y2="16" />
            </svg>
          </div>
          <span className="truncate max-w-[56px] text-emerald-400 font-bold">{t('nav_tokenize')}</span>
        </Link>

        {/* Market */}
        <Link
          href="/market"
          className={`flex flex-col items-center justify-center flex-1 py-1 text-[10px] font-semibold transition ${
            pathname === '/market' ? 'text-emerald-400 font-bold' : 'text-slate-400 hover:text-white'
          }`}
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="9" cy="21" r="1" /><circle cx="20" cy="21" r="1" />
            <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6" />
          </svg>
          <span className="truncate max-w-[56px] mt-0.5">{t('nav_market')}</span>
        </Link>

        {/* More Menu Drawer Trigger */}
        <button
          type="button"
          onClick={toggleMobileOpen}
          className={`flex flex-col items-center justify-center flex-1 py-1 text-[10px] font-semibold transition ${
            mobileOpen ? 'text-emerald-400 font-bold' : 'text-slate-400 hover:text-white'
          }`}
          aria-label="Open full menu"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="12" cy="12" r="1" /><circle cx="19" cy="12" r="1" /><circle cx="5" cy="12" r="1" />
          </svg>
          <span className="truncate max-w-[56px] mt-0.5">{t('menu_mobile')}</span>
        </button>
      </nav>
    </>
  );
}

